package com.minimarket.cliente.controller; import org.springframework.security.access.prepost.PreAuthorize;
import com.minimarket.cliente.dto.*; import com.minimarket.cliente.service.ClienteService; import com.minimarket.common.ApiResponse; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @PreAuthorize("hasAuthority('CLIENTE_ADMINISTRAR')") @RequestMapping("/api/clientes") @RequiredArgsConstructor public class ClienteController{private final ClienteService s;@GetMapping public ApiResponse<Page<ClienteResponseDTO>> listar(@RequestParam(required=false)String busqueda,Pageable p){return ApiResponse.ok(s.listar(busqueda,p));}@GetMapping("/documento/{numero}")public ApiResponse<ClienteResponseDTO> doc(@PathVariable String numero){return ApiResponse.ok(s.porDocumento(numero));}@GetMapping("/{id}")public ApiResponse<ClienteResponseDTO> one(@PathVariable Long id){return ApiResponse.ok(s.obtener(id));}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ApiResponse<ClienteResponseDTO> crear(@Valid@RequestBody ClienteRequestDTO r){return ApiResponse.ok(s.crear(r));}@PutMapping("/{id}")public ApiResponse<ClienteResponseDTO> upd(@PathVariable Long id,@Valid@RequestBody ClienteRequestDTO r){return ApiResponse.ok(s.actualizar(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void> del(@PathVariable Long id){s.desactivar(id);return ApiResponse.ok(null,"Cliente desactivado");}}